index 38f05cb18..bcb90a201 100644
--- a/android/guava/src/com/google/common/escape/CharEscaper.java
+++ b/android/guava/src/com/google/common/escape/CharEscaper.java
@@ -160,21 +160,6 @@ public abstract class CharEscaper extends Escaper {
     return new String(dest, 0, destIndex);
   }

-  /**
-   * Helper method to grow the character buffer as needed, this only happens once in a while so it's
-   * ok if it's in a method call. If the index passed in is 0 then no copying will be done.
-   */
-  private static char[] growBuffer(char[] dest, int index, int size) {
-    if (size < 0) { // overflow - should be OutOfMemoryError but GWT/j2cl don't support it
-      throw new AssertionError("Cannot increase internal buffer any further");
-    }
-    char[] copy = new char[size];
-    if (index > 0) {
-      arraycopy(dest, 0, copy, 0, index);
-    }
-    return copy;
-  }
-
   /** The multiplier for padding to use when growing the escape buffer. */
   private static final int DEST_PAD_MULTIPLIER = 2;
 }
diff --git a/android/guava/src/com/google/common/escape/Escaper.java b/android/guava/src/com/google/common/escape/Escaper.java
index 924e3d34c..cf1d3543f 100644
--- a/android/guava/src/com/google/common/escape/Escaper.java
+++ b/android/guava/src/com/google/common/escape/Escaper.java
@@ -14,6 +14,8 @@

 package com.google.common.escape;

+import static java.lang.System.arraycopy;
+
 import com.google.common.annotations.GwtCompatible;
 import com.google.common.base.Function;
 import com.google.errorprone.annotations.DoNotMock;
@@ -91,4 +93,19 @@ public abstract class Escaper {
   public final Function<String, String> asFunction() {
     return asFunction;
   }
+
+  /**
+   * Helper method to grow the character buffer as needed, this only happens once in a while so it's
+   * ok if it's in a method call. If the index passed in is 0 then no copying will be done.
+   */
+  static char[] growBuffer(char[] dest, int index, int size) {
+    if (size < 0) { // overflow - should be OutOfMemoryError but GWT/j2cl don't support it
+      throw new AssertionError("Cannot increase internal buffer any further");
+    }
+    char[] copy = new char[size];
+    if (index > 0) {
+      arraycopy(dest, 0, copy, 0, index);
+    }
+    return copy;
+  }
 }
